    client = TestClient(app)
    response = client.post("/", data={"kind": "defaults", "value": ""})
    assert response.status_code == 200
    assert response.json() == {
        "values": {
            "kind": "defaults",
            "value": "default",
            "items": ["default"],
            "enabled": False,
            "nullable": False,
        },
        "set": {"kind": "defaults", "enabled": False, "nullable": False},
